def select_agents(values):
    selected = set()
    for value in values or ():
        for name in value.split(","):
            name = AGENT_ALIASES.get(name.strip().lower(), name.strip().lower())
            if name == "all":
                selected.update(AGENTS)
            elif name in AGENTS:
                selected.add(name)
            else:
                raise ValueError(f"Unknown agent: {name!r}. Run git-workflow agents for supported names.")
    return tuple(name for name in AGENTS if name in selected)


def show_agents(ui):
    ui.table("Supported agents (ID / repo / user)", [
        (name, f"{info[0]} | {info[1]}/git-workflow | ~/{info[2]}/git-workflow")
        for name, info in AGENTS.items()
    ])
    ui.line("Shared .agents/skills locations can be discovered by other compatible agents.")
    for name in AGENTS:
        custom = custom_user_skills(name)
        if custom is not None:
            ui.line(f"User override: {name} -> {custom / 'git-workflow'}")


def custom_user_skills(agent):
    """Honor documented user config roots without editing host configuration."""
    variable, suffix = {
        "claude-code": ("CLAUDE_CONFIG_DIR", "skills"),
        "opencode": ("XDG_CONFIG_HOME", "opencode/skills"),
        "amp": ("XDG_CONFIG_HOME", "agents/skills"),
        "hermes": ("HERMES_HOME", "skills"),
        "oh-my-pi": ("PI_CODING_AGENT_DIR", "skills"),
    }.get(agent, (None, None))
    value = os.environ.get(variable, "") if variable else ""
    if value:
        base = Path(value).expanduser()
        if not base.is_absolute():
            raise ValueError(f"{variable} must be an absolute directory")
        return base / suffix
    if agent == "oh-my-pi":
        profile = os.environ.get("OMP_PROFILE") or os.environ.get("PI_PROFILE")
        if profile and profile != "default":
            if not re.fullmatch(r"[a-zA-Z0-9_-]+", profile):
                raise ValueError("Unsafe Oh My Pi profile name")
            return Path.home() / ".omp/profiles" / profile / "agent/skills"
    return None


def agent_base(agent, global_install):
    if not global_install:
        return AGENTS[agent][1]
    destination = custom_user_skills(agent) or Path.home() / AGENTS[agent][2]
    identity = os.path.normcase(os.path.abspath(destination))
    # Config roots may alias another agent's native directory. Use one manifest
    # key per physical destination, even when the first owner is not selected.
    for name, info in AGENTS.items():
        try:
            custom = custom_user_skills(name)
        except ValueError:
            # An unrelated agent's invalid override cannot block this target.
            # The selected agent was already validated above.
            continue
        candidate = custom or Path.home() / info[2]
        if os.path.normcase(os.path.abspath(candidate)) == identity:
            return "@" + name if custom is not None else info[2]
    raise ValueError("Cannot determine agent destination")


def location(root, rel):
    parts = PurePosixPath(rel).parts
    if parts and parts[0].startswith("@"):
        name = parts[0][1:]
        if name not in AGENTS or custom_user_skills(name) is None:
            raise ValueError("Restore the agent's original environment/profile before managing its manifest: " + str(name))
        return custom_user_skills(name).joinpath(*parts[1:])
    return root.joinpath(*parts)


def agent_files(agent, global_install):
    base = agent_base(agent, global_install) + "/git-workflow/"
    result = [base + name.removeprefix(".agents/skills/git-workflow/") for name in load_payload()]
    if not global_install and base.startswith(".agents/skills/"):
        result.append(".agents/rules/git-workflow.md")
    return result


def manifest_agents(manifest, global_install):
    """Validate ownership before any reads or writes, including legacy manifests."""
    if not isinstance(manifest, dict) or manifest.get("package") != "git-workflow" or not isinstance(manifest.get("files"), dict):
        raise ValueError("Unrecognized installer manifest")
    for rel, expected in manifest["files"].items():
        if not isinstance(rel, str) or not owned_path(rel, global_install) or not isinstance(expected, str) or not re.fullmatch(r"[0-9a-f]{64}", expected):
            raise ValueError("Unsafe installer manifest entry: " + str(rel))
    if "agents" not in manifest:
        # Old local installs were shared by the three original targets.
        return {agent: {"version": manifest.get("version", "?"), "files": [
            rel for rel in manifest["files"] if not global_install or rel.startswith(AGENTS[agent][2] + "/git-workflow/")]}
                for agent in LEGACY_AGENTS}
    records = manifest["agents"]
    if manifest.get("schema") != 2 or not isinstance(records, dict) or not records:
        raise ValueError("Unrecognized agent ownership manifest")
    covered = set()
    for agent, record in records.items():
        if agent not in AGENTS or not isinstance(record, dict) or not isinstance(record.get("files"), list) or not isinstance(record.get("version"), str):
            raise ValueError("Unsafe agent ownership manifest")
        allowed = set(agent_files(agent, global_install))
        if global_install and "target" in record and record["target"] != str(location(Path.home(), agent_base(agent, True) + "/git-workflow")):
            raise ValueError("Agent target changed; restore the original environment/profile: " + agent)
        for rel in record["files"]:
            legacy_allowed = (agent in LEGACY_AGENTS and isinstance(rel, str) and
                              legacy_owned_path(rel, global_install) and
                              (not global_install or rel.startswith(AGENTS[agent][2] + "/git-workflow/")))
            if not isinstance(rel, str) or rel not in manifest["files"] or (rel not in allowed and not legacy_allowed):
                raise ValueError("Unsafe agent ownership path: " + str(rel))
            covered.add(rel)
    if covered != set(manifest["files"]):
        raise ValueError("Manifest has files without an agent owner")
    return {name: dict(record, files=list(record["files"])) for name, record in records.items()}


def requires_project_block(records):
    return any(".agents/rules/git-workflow.md" in record["files"] or
               ".agents/git-workflow.rules.md" in record["files"] for record in records.values())


