class TerminalUI:
    """Small terminal renderer shared by the native and standalone Python CLI."""

    def __init__(self, plain=False, no_color=False, stream=None):
        self.stream = sys.stdout if stream is None else stream
        self.enabled = bool(self.stream.isatty() and not plain and not os.environ.get("CI")
                            and os.environ.get("TERM") != "dumb")
        try:
            columns = os.get_terminal_size(self.stream.fileno()).columns
        except (OSError, ValueError):
            columns = shutil.get_terminal_size((80, 24)).columns
        self.width = max(20, min(columns - 1, 100))
        self.color = self.enabled and not no_color and "NO_COLOR" not in os.environ
        if self.color and os.name == "nt":
            try:
                import ctypes
                import msvcrt
                console = ctypes.windll.kernel32
                console.GetStdHandle.restype = ctypes.c_void_p
                console.GetConsoleMode.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_ulong)]
                console.SetConsoleMode.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
                handle = msvcrt.get_osfhandle(self.stream.fileno())
                mode = ctypes.c_ulong()
                self.color = bool(console.GetConsoleMode(handle, ctypes.byref(mode))
                                  and console.SetConsoleMode(handle, mode.value | 4))
            except (AttributeError, OSError):
                self.color = False
        try:
            "✓✗●├└─│".encode(self.stream.encoding or "ascii")
            self.unicode = self.enabled
        except UnicodeError:
            self.unicode = False

    def paint(self, value, style="cyan"):
        colors = {"cyan": "36", "green": "32", "yellow": "33", "red": "31", "dim": "2", "bold": "1"}
        return f"\033[{colors[style]}m{value}\033[0m" if self.color else value

    def line(self, value="", style=None):
        # Paths and error text can contain terminal control characters.
        value = "".join(char if char >= " " or char == "\n" else "?" for char in str(value))
        parts = (textwrap.wrap(value, self.width, replace_whitespace=False, drop_whitespace=False)
                 if self.enabled and len(value) > self.width and "\n" not in value else [value])
        for part in parts:
            print(self.paint(part, style) if style else part, file=self.stream)

    def banner(self):
        logo = BANNER
        if not getattr(sys, "frozen", False):
            try:
                logo = (Path(__file__).resolve().parent / "assets/banner/ASCIILogo.txt").read_text(encoding="utf-8-sig")
            except (OSError, UnicodeError):
                pass  # The Python release remains standalone without the asset folder.
        try:
            logo.encode(self.stream.encoding or "ascii")
            compatible = self.unicode
        except UnicodeError:
            compatible = False
        if not compatible:
            logo = logo.translate(str.maketrans({"█": "#", "═": "=", "║": "|", "╔": "+",
                                                "╗": "+", "╚": "+", "╝": "+", "┄": "-"}))
        lines = logo.splitlines()
        art_width = max((len(line.rstrip()) for line in lines if len(set(line)) > 1), default=0)
        if art_width <= self.width:
            for line in lines:
                self.line(line.rstrip()[:self.width], "cyan")
        else:
            self.line("[git] GIT SKILLS", "cyan")
            self.line("Agentic Git Workflow Skill", "dim")
        self.line(f"  Skill installer · v{VERSION}" if self.unicode else f"  Skill installer | v{VERSION}", "dim")
        self.line()

    def panel(self, title, lines, style="cyan"):
        if not self.enabled:
            self.line(title)
            for line in lines:
                self.line(line)
            return
        inside = self.width - 4
        self.line("+" + "-" * (self.width - 2) + "+", style)
        for line in [title, *lines]:
            for part in textwrap.wrap(str(line), inside, replace_whitespace=False) or [""]:
                self.line("| " + part.ljust(inside) + " |", style if line == title else None)
        self.line("+" + "-" * (self.width - 2) + "+", style)

    def table(self, title, rows):
        self.line(title, "bold")
        if not rows:
            self.line("  No changes.", "dim")
            return
        if not self.enabled:
            for left, right in rows:
                self.line(f"  {left}: {right}")
            return
        first = min(max(len(str(left)) for left, _ in rows), 20, max(4, self.width // 3))
        second = self.width - first - 7
        border = "+" + "-" * (first + 2) + "+" + "-" * (second + 2) + "+"
        self.line(border, "dim")
        for left, right in rows:
            left_lines = textwrap.wrap(str(left), first) or [""]
            right_lines = textwrap.wrap(str(right), second) or [""]
            for index in range(max(len(left_lines), len(right_lines))):
                one = left_lines[index] if index < len(left_lines) else ""
                two = right_lines[index] if index < len(right_lines) else ""
                self.line(f"| {one:<{first}} | {two:<{second}} |")
        self.line(border, "dim")

    def tree(self, title, rows):
        self.line(title, "bold")
        for index, (name, description) in enumerate(rows):
            branch = ("└─" if index == len(rows) - 1 else "├─") if self.unicode else ("`-" if index == len(rows) - 1 else "|-")
            prefix = "  " + branch + " "
            for number, line in enumerate(textwrap.wrap(f"{name}  {description}", max(10, self.width - 5))):
                self.line((prefix if number == 0 else "     ") + line)

    def step(self, number, title):
        if self.enabled:
            self.line(f"{'●' if self.unicode else '>'} [{number}/4] {title}", "cyan")

    def outcome(self, title, lines, ok=True):
        icon = ("✓" if ok else "✗") if self.unicode else ("OK" if ok else "!")
        self.panel(f"{icon} {title}", lines, "green" if ok else "red")

    @contextmanager
    def spinner(self, label):
        if not self.enabled:
            yield
            return
        stopped = threading.Event()
        text = label[:self.width - 4]

        def animate():
            frame = 0
            while not stopped.is_set():
                self.stream.write("\r" + self.paint("|/-\\"[frame % 4] + " " + text))
                self.stream.flush()
                frame += 1
                stopped.wait(0.1)

        worker = threading.Thread(target=animate, daemon=True)
        worker.start()
        try:
            yield
        finally:
            stopped.set()
            worker.join()
            self.stream.write("\r" + " " * (len(text) + 2) + "\r")
            self.stream.flush()

    @contextmanager
    def progress(self, total, label):
        completed = 0

        def advance():
            nonlocal completed
            completed += 1
            if self.enabled:
                size = min(22, max(4, self.width // 4))
                filled = completed * size // max(total, 1)
                bar = "#" * filled + "-" * (size - filled)
                text = f"[{bar}] {completed}/{total} {label}"
                self.stream.write("\r" + self.paint(text[:self.width], "green"))
                self.stream.flush()

        try:
            yield advance
        finally:
            if self.enabled and completed:
                self.stream.write("\n")
                self.stream.flush()


