def error_guidance(message):
    if "--replace" in message or "Modified" in message or "Different existing" in message:
        return "Review the listed files. Use --replace --apply only to replace them with exact backups."
    if "No Git" in message:
        return "Run inside a Git repo, choose --project PATH, or use --global."
    if "directory" in message or "path" in message.lower() or "symlink" in message.lower():
        return "Choose an existing, regular project directory with --project PATH."
    if "manifest" in message.lower() or "AGENTS.md" in message:
        return "Review the named metadata or managed block before retrying."
    return "Run git-workflow --help or git-workflow commands for available operations and examples."


def report_conflicts(ui, message, paths):
    error = TerminalUI(plain=not ui.enabled, no_color=not ui.color, stream=sys.stderr)
    error.outcome("Installation blocked", [message, *paths, "Next: " + error_guidance(message)], ok=False)


class WorkflowParser(argparse.ArgumentParser):
    def __init__(self, *args, ui=None, **kwargs):
        self.ui = ui or TerminalUI()
        super().__init__(*args, **kwargs)

    def print_help(self, file=None):
        if self.ui.enabled and file is None:
            self.ui.banner()
            self.ui.tree("Command tree", CLI_COMMANDS)
            self.ui.line()
        super().print_help(file)
        if self.ui.enabled and file is None:
            self.ui.panel("Quick start", ["git-workflow install", "git-workflow install --apply",
                                          "git-workflow install --global --apply", "git-workflow menu"])

    def error(self, message):
        self.print_usage(sys.stderr)
        ui = TerminalUI(plain=not self.ui.enabled, no_color=not self.ui.color, stream=sys.stderr)
        ui.outcome("Command error", [message, "Next: " + error_guidance(message)], ok=False)
        self.exit(2)


def installation_status(root, global_install, ui, agents=None):
    manifest_rel = ".config/git-workflow/install.json" if global_install else ".agents/git-workflow-install.json"
    path = check_path(root, manifest_rel)
    if not path.exists():
        ui.panel("Installation status", ["No managed Git Workflow installation found.", "Target: " + str(root),
                                         "Next: git-workflow install" + (" --global" if global_install else "")])
        return 0
    with ui.spinner("Verify installation hashes"):
        manifest = json.loads(path.read_bytes())
        records = manifest_agents(manifest, global_install)
        selected = agents or tuple(records)
        names = {name for agent in selected if agent in records for name in records[agent]["files"]}
        problems = []
        for name, expected in manifest["files"].items():
            if (not isinstance(name, str) or not owned_path(name, global_install)
                    or not isinstance(expected, str) or len(expected) != 64
                    or any(char not in "0123456789abcdef" for char in expected)):
                raise ValueError("Unsafe installer manifest entry")
            if name not in names:
                continue
            item = check_path(root, name)
            if not item.exists():
                problems.append(("MISSING", name))
            elif digest(item.read_bytes()) != expected:
                problems.append(("MODIFIED", name))
    ui.table("Installation status", [
        ("Scope", "Current user" if global_install else "Project"), ("Target", str(root)),
        ("Recorded version", str(manifest.get("version", "Unknown"))), ("Package version", VERSION),
        ("Manifest files", str(len(names))),
        ("Hash check", f"{len(problems)} changed or missing" if problems else "All manifest files intact"),
    ])
    ui.table("Agent installations", [(AGENTS[name][0], records[name]["version"] if name in records else "Not installed")
                                     for name in selected])
    if problems:
        ui.table("Files to review", problems)
    ui.line("Read-only check of this scope; use your agent to identify the active skill.", "dim")
    return 1 if problems else 0


def interactive_menu(parser, args, ui, setup=False):
    if not sys.stdin.isatty() or not sys.stdout.isatty() or os.environ.get("CI"):
        parser.error("The menu requires an interactive terminal. Use install, uninstall, status, or commands instead.")
    ui.banner()
    while True:
        ui.table("Interactive menu", [
            ("1", "Install / update skill"), ("2", "Uninstall skill"),
            ("3", "Installation status"), ("4", "Command tree"),
            ("5", "Help and examples"), ("6", "Supported agents and paths"), ("0", "Exit"),
        ])
        try:
            choice = "1" if setup else input("Select [0-6, Enter = exit]: ").strip()
            if choice in ("", "0", "q"):
                return 0
            if choice == "4":
                show_commands(ui)
                continue
            if choice == "5":
                parser.print_help()
                continue
            if choice == "6":
                show_agents(ui)
                continue
            if choice not in ("1", "2", "3"):
                ui.outcome("Unknown selection", ["Choose a number from 0 to 6."], ok=False)
                continue
            command = {"1": "install", "2": "uninstall", "3": "status"}[choice]
            show_agents(ui)
            agent_choice = input("Agent IDs (comma-separated), all, or Enter = installed/default Codex; 0 = back: ").strip()
            if agent_choice == "0":
                if setup:
                    return 0
                continue
            try:
                chosen = select_agents([agent_choice]) if agent_choice else select_agents(args.agent)
            except ValueError as exc:
                ui.outcome("Unknown agent", [str(exc)], ok=False)
                continue
            ui.table("Scope", [("1", "Project (detect root from the current directory)"),
                               ("2", "Current user / global"), ("3", "Explicit project directory"), ("0", "Back")])
            default_scope = "2" if args.global_install else "1"
            scope = input(f"Scope [{default_scope}]: ").strip() or default_scope
            if scope == "0":
                if setup:
                    return 0
                continue
            selection = [command]
            for agent in chosen:
                selection.extend(("--agent", agent))
            if scope == "2":
                selection.append("--global")
            elif scope == "3":
                target = input("Existing project path (Enter = back): ").strip()
                if not target:
                    continue
                selection.extend(("--project", target))
            elif scope == "1":
                if args.project:
                    selection.extend(("--project", args.project))
            else:
                ui.outcome("Unknown scope", ["Choose 1, 2, 3, or 0."], ok=False)
                continue
            if args.plain:
                selection.append("--plain")
            if args.no_color:
                selection.append("--no-color")
            if args.replace and command != "status":
                selection.append("--replace")
            result = main(selection)
            if result == 130:
                return 130
            if command != "status" and result == 0:
                ui.line("Existing edits are protected. Replacement is available through --replace.", "dim")
                if input("Apply this plan? [y/N]: ").strip().lower() in ("y", "yes"):
                    result = main(selection + ["--apply"])
            if setup:
                return result
        except SystemExit as exc:
            if exc.code not in (0, 2):
                raise
        except (EOFError, KeyboardInterrupt):
            ui.line("\nMenu closed. Pending changes were not applied.", "dim")
            return 0


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def load_payload() -> dict[str, str]:
    payload = json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)))
    if not isinstance(payload, dict):
        raise ValueError("Invalid package payload")
    for key, value in payload.items():
        rel = PurePosixPath(key)
        if rel.is_absolute() or ".." in rel.parts or "\\" in key or ":" in key or not isinstance(value, str):
            raise ValueError("Unsafe package path")
        if not key.startswith(".agents/skills/git-workflow/"):
            raise ValueError("Unexpected package path")
    version_path = ".agents/skills/git-workflow/VERSION"
    if version_path in payload:
        raise ValueError("Package version file must be generated from VERSION")
    payload[version_path] = VERSION + "\n"
    return payload

def check_path(root: Path, rel: str) -> Path:
    target = location(root, rel)
    boundary = Path(target.anchor) if rel.startswith("@") else root
    cursor = target
    while cursor != boundary:
        if cursor.is_symlink():
            raise ValueError(f"Refusing symlink destination: {cursor}")
        if cursor.exists() and cursor != target and not cursor.is_dir():
            raise ValueError(f"Parent is not a directory: {cursor}")
        cursor = cursor.parent
    if boundary.is_symlink():
        raise ValueError(f"Refusing symlink destination: {boundary}")
    if target.exists() and not target.is_file():
        raise ValueError(f"Destination is not a regular file: {target}")
    return target

def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    fd, temp = tempfile.mkstemp(prefix=".git-workflow-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.chmod(temp, mode)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)

def update_agents(old: bytes, replace: bool) -> bytes:
    text = old.decode("utf-8")
    newline = "\r\n" if "\r\n" in text else "\n"
    block = AGENTS_BLOCK.replace("\n", newline)
    if BEGIN not in text and END not in text:
        return (text + ((newline * 2) if text and not text.endswith(newline * 2) else "") + block + newline).encode("utf-8")
    if text.count(BEGIN) != 1 or text.count(END) != 1 or text.index(END) < text.index(BEGIN):
        raise ValueError("Malformed/duplicate Git Workflow block in AGENTS.md; review it manually")
    start, finish = text.index(BEGIN), text.index(END) + len(END)
    if text[start:finish] not in (block, OLD_AGENTS_BLOCK.replace("\n", newline), PREVIOUS_AGENTS_BLOCK.replace("\n", newline)) and not replace:
        raise ValueError("The managed AGENTS.md block differs; review it or use --replace with a backup")
    return (text[:start] + block + text[finish:]).encode("utf-8")

def owned_path(rel: str, global_install: bool) -> bool:
    if not isinstance(rel, str):
        return False
    path = PurePosixPath(rel)
    if path.is_absolute() or path.as_posix() != rel or ".." in path.parts or "\\" in rel or ":" in rel:
        return False
    return (any(rel.startswith(info[2 if global_install else 1] + "/git-workflow/")
                for info in AGENTS.values()) or
            (global_install and any(rel.startswith("@" + name + "/git-workflow/") for name in AGENTS)) or
            legacy_owned_path(rel, global_install))


def legacy_owned_path(rel: str, global_install: bool) -> bool:
    parts = PurePosixPath(rel).parts
    if (not parts or PurePosixPath(rel).is_absolute() or
            PurePosixPath(rel).as_posix() != rel or ".." in parts or
            "\\" in rel or ":" in rel):
        return False
    if global_install:
        return any(parts[:len(prefix)] == prefix and len(parts) > len(prefix)
                   for prefix in ((".agents", "skills", "git-workflow"),
                                  (".gemini", "config", "skills", "git-workflow"),
                                  (".gemini", "antigravity-cli", "skills", "git-workflow")))
    return (rel in (".agents/rules/git-workflow.md", ".agents/git-workflow.rules.md")
            or (len(parts) >= 4 and parts[:2] == (".agents", "skills") and parts[2] in OLD_NAMES)
            or (len(parts) == 3 and parts[:2] in ((".agent", "workflows"), (".agents", "workflows"))
                and parts[2].removesuffix(".md") in OLD_NAMES and parts[2].endswith(".md")))

def remove_agents_block(old: bytes, replace: bool) -> Optional[bytes]:
    content = old.decode("utf-8")
    if BEGIN not in content and END not in content:
        return old
    if content.count(BEGIN) != 1 or content.count(END) != 1 or content.index(END) < content.index(BEGIN):
        raise ValueError("Malformed/duplicate Git Workflow block in AGENTS.md; review it manually")
    start, finish = content.index(BEGIN), content.index(END) + len(END)
    newline = "\r\n" if "\r\n" in content else "\n"
    known = (AGENTS_BLOCK, OLD_AGENTS_BLOCK, PREVIOUS_AGENTS_BLOCK)
    if content[start:finish] not in tuple(block.replace("\n", newline) for block in known) and not replace:
        raise ValueError("The managed AGENTS.md block differs; review it or use --replace with a backup")
    remaining = content[:start] + content[finish:]
    return remaining.encode("utf-8") if remaining.strip() else None

def uninstall(root: Path, manifest_rel: str, global_install: bool, apply: bool, replace: bool,
              ui: Optional[TerminalUI] = None, agents=None) -> int:
    ui = ui or TerminalUI(plain=True)
    ui.step(1, "Read installation manifest")
    manifest_path = check_path(root, manifest_rel)
    if not manifest_path.exists():
        if ui.enabled:
            ui.outcome("Nothing to remove", ["No managed Git Workflow installation found; no files changed."])
        else:
            print("No managed Git Workflow installation found; no files changed.")
        ui.step(4, "Nothing to remove")
        return 0
    manifest_bytes = manifest_path.read_bytes()
    with ui.spinner("Read installation metadata"):
        manifest = json.loads(manifest_bytes)
    records = manifest_agents(manifest, global_install)
    selected = agents or tuple(records)
    if not set(selected).intersection(records):
        ui.outcome("Nothing to remove", ["Selected agents have no managed installation."])
        return 0
    remaining = {name: record for name, record in records.items() if name not in selected}
    retained = {rel for record in remaining.values() for rel in record["files"]}
    plans, conflicts = [], []
    ui.step(2, "Inspect managed files and plan removal")
    for rel, expected_hash in manifest["files"].items():
        if (not isinstance(rel, str) or not owned_path(rel, global_install) or
                not isinstance(expected_hash, str) or len(expected_hash) != 64 or
                any(ch not in "0123456789abcdef" for ch in expected_hash)):
            raise ValueError("Unsafe installer manifest entry: " + str(rel))
        if rel in retained:
            continue
        path = check_path(root, rel)
        if not path.exists():
            continue
        old = path.read_bytes()
        if digest(old) != expected_hash and not replace:
            conflicts.append(rel)
        plans.append((rel, path, old, None))
    if not global_install and not requires_project_block(remaining):
        agents_path = check_path(root, "AGENTS.md")
        if agents_path.exists():
            old = agents_path.read_bytes()
            new = remove_agents_block(old, replace)
            if new != old:
                plans.append(("AGENTS.md", agents_path, old, new))
    if conflicts:
        report_conflicts(ui, "No files changed. Modified package files require review or --replace:", conflicts)
        return 2
    if remaining:
        updated = dict(manifest, schema=2, agents=remaining,
                       files={rel: value for rel, value in manifest["files"].items() if rel in retained})
        next_manifest = (json.dumps(updated, indent=2) + "\n").encode("utf-8")
    else:
        next_manifest = None
    plans.append((manifest_rel, manifest_path, manifest_bytes, next_manifest))
    ui.table("Agents to uninstall", [(name, AGENTS[name][0]) for name in selected if name in records])
    if remaining:
        ui.line("Retained agents: " + ", ".join(remaining) + "; shared files stay installed.")
    if ui.enabled:
        ui.panel("Removal plan", [f"Installed version: {manifest.get('version', '?')}", f"Files: {len(plans)}"])
    else:
        print(f"Git Workflow {manifest.get('version', '?')}: uninstall {'current user' if global_install else 'this project'}")
    if ui.enabled:
        ui.table("Removal plan", [("UPDATE" if new is not None else "REMOVE", rel) for rel, _, _, new in plans])
    else:
        for rel, _, _, new in plans:
            print(("UPDATE " if new is not None else "REMOVE ") + rel)
    if not apply:
        ui.step(3, "Review preview")
        if ui.enabled:
            ui.panel("Preview", ["Dry run only. Add --apply to uninstall."])
        else:
            print("Dry run only. Add --apply to uninstall.")
        ui.step(4, "Preview complete; no files changed")
        return 0
    ui.step(3, "Verify paths and save exact backups")
    for rel, path, old, _ in plans:
        check_path(root, rel)
        if not path.exists() or path.read_bytes() != old:
            raise ValueError(f"File changed during uninstall preflight: {rel}")
    backup = Path(tempfile.mkdtemp(prefix="git-workflow-uninstall-backup-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S-")))
    for rel, _, old, _ in plans:
        target = backup.joinpath(*PurePosixPath(rel).parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(old)
    ui.line("Exact previous-file backup: " + str(backup))
    completed = []
    try:
        with ui.progress(len(plans), "Remove managed files") as advance:
            for rel, path, old, new in plans:
                check_path(root, rel)
                if not path.exists() or path.read_bytes() != old:
                    raise ValueError(f"File changed during uninstall: {rel}")
                completed.append((path, old, new))
                if new is None:
                    path.unlink()
                else:
                    atomic_write(path, new)
                advance()
        # Only prune empty package directories from this removal transaction.
        bases = set()
        for rel, _, _, new in plans:
            parts = PurePosixPath(rel).parts
            if new is None:
                if "skills" in parts:
                    index = parts.index("skills") + 1
                    if len(parts) > index and parts[index] in OLD_NAMES:
                        bases.add(parts[:index + 1])
                elif parts and parts[0].startswith("@") and len(parts) > 2:
                    bases.add(parts[:2])
        for base in bases:
            folder = location(root, PurePosixPath(*base).as_posix())
            if folder.is_dir() and not folder.is_symlink():
                for subdir in sorted(folder.rglob("*"), key=lambda item: len(item.parts), reverse=True):
                    if subdir.is_dir() and not subdir.is_symlink():
                        try: subdir.rmdir()
                        except OSError: pass
                try: folder.rmdir()
                except OSError: pass
    except BaseException:
        for path, old, written in reversed(completed):
            if written is None and not path.exists():
                atomic_write(path, old)
            elif written is not None and path.is_file() and not path.is_symlink() and path.read_bytes() == written:
                atomic_write(path, old)
        raise
    ui.step(4, "Uninstall complete")
    if ui.enabled:
        ui.outcome("Uninstalled", ["Uninstalled managed files; unrelated files remain intact.",
                                  "Backup: " + str(backup)])
    else:
        print("Uninstalled managed files; unrelated files remain intact.")
    return 0

def manage_installation(
    root: Path, *, global_install: bool = False, remove: bool = False,
    apply: bool = False, replace: bool = False, ui: Optional[TerminalUI] = None,
    agents=None,
) -> int:
    ui = ui or TerminalUI(plain=True)
    if remove:
        manifest_rel = ".config/git-workflow/install.json" if global_install else ".agents/git-workflow-install.json"
        return uninstall(root, manifest_rel, global_install, apply, replace, ui, agents)
    ui.step(1, "Read bundled skill and installation metadata")
    with ui.spinner("Load bundled skill"):
        payload = load_payload()
    manifest_rel = ".config/git-workflow/install.json" if global_install else ".agents/git-workflow-install.json"
    manifest_path = check_path(root, manifest_rel)
    old_manifest = None
    if manifest_path.exists():
        old_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    records = manifest_agents(old_manifest, global_install) if old_manifest else {}
    selected = agents or tuple(records) or ("codex",)
    old_hashes = (old_manifest or {}).get("files",{})
    desired = {}
    for agent in selected:
        base = agent_base(agent, global_install) + "/git-workflow/"
        files = []
        for key, value in payload.items():
            suffix = key.removeprefix(".agents/skills/git-workflow/")
            rel = base + suffix
            desired[rel] = value.encode("utf-8")
            files.append(rel)
        if not global_install and base.startswith(".agents/skills/"):
            desired[".agents/rules/git-workflow.md"] = RULE.encode("utf-8")
            files.append(".agents/rules/git-workflow.md")
        records[agent] = {"version": VERSION, "files": files}
        if global_install:
            records[agent]["target"] = str(location(root, base.rstrip("/")))
    # Update version attribution for every owner of a physically shared copy.
    for record in records.values():
        if set(record["files"]).intersection(desired):
            record["version"] = VERSION
    retained = {rel for record in records.values() for rel in record["files"]}
    hashes = {rel: value for rel, value in old_hashes.items() if rel in retained}
    hashes.update({rel: digest(data) for rel, data in desired.items()})
    if not global_install and requires_project_block(records):
        agent_path = check_path(root, "AGENTS.md")
        desired["AGENTS.md"] = update_agents(agent_path.read_bytes() if agent_path.exists() else b"", replace)
    manifest = {"package": "git-workflow", "schema": 2, "version": VERSION, "agents": records, "files": hashes}
    desired[manifest_rel] = (json.dumps(manifest,indent=2) + "\n").encode("utf-8")
    changes, removals, conflicts = [], [], []
    ui.step(2, "Inspect files and plan changes")
    for rel, data in desired.items():
        path = check_path(root, rel)
        old = path.read_bytes() if path.exists() else None
        if old == data:
            continue
        owned = old is not None and digest(old) == old_hashes.get(rel)
        if old is not None and rel not in ("AGENTS.md", manifest_rel) and not owned and not replace:
            conflicts.append(rel)
        changes.append((rel, path, old, data))
    if old_manifest:
        for rel, expected_hash in old_hashes.items():
            if rel in retained:
                continue
            parts = PurePosixPath(rel).parts
            permitted = owned_path(rel, global_install)
            if not permitted or ".." in parts or ":" in rel or "\\" in rel:
                raise ValueError("Unsafe old manifest path: " + rel)
            path = check_path(root, rel)
            if path.exists():
                old = path.read_bytes()
                if digest(old) != expected_hash and not replace:
                    conflicts.append(rel)
                removals.append((rel,path,old))
    if conflicts:
        report_conflicts(ui, "No files changed. Different existing files require review or --replace:", conflicts)
        return 2
    scope = "current user" if global_install else "this project"
    ui.table("Selected agents", [(name, str(location(root, agent_base(name, global_install) + "/git-workflow")))
                                 for name in selected])
    if ui.enabled:
        ui.panel("Installation plan", [f"One skill, {len(COMMAND_NAMES)} agent commands",
                 f"{len(changes)} writes, {len(removals)} removals"])
    else:
        print(f"Git Workflow {VERSION}: one skill for {scope}, {len(COMMAND_NAMES)} commands, {len(changes)} writes, {len(removals)} removals")
    if not changes and not removals:
        if ui.enabled:
            ui.outcome("Up to date", ["Already installed; no changes needed."])
        else:
            print("Already installed; no changes needed.")
        ui.step(4, "Installation is up to date")
        return 0
    if ui.enabled:
        ui.table("File plan", [("UPDATE" if old is not None else "CREATE", rel) for rel, _, old, _ in changes]
                 + [("REMOVE", rel) for rel, _, _ in removals])
    else:
        for rel, _, old, _ in changes:
            print(("UPDATE " if old is not None else "CREATE ") + rel)
        for rel, _, _ in removals:
            print("REMOVE " + rel)
    if not apply:
        ui.step(3, "Review preview")
        if ui.enabled:
            ui.panel("Preview", ["Dry run only. Add --apply to install."])
        else:
            print("Dry run only. Add --apply to install.")
        ui.step(4, "Preview complete; no files changed")
        return 0
    ui.step(3, "Verify paths and save required backups")
    # Preflight all paths before writing anything, then guard each write against races.
    for rel, path, old, _ in changes:
        check_path(root, rel)
        if (path.read_bytes() if path.exists() else None) != old:
            raise ValueError(f"File changed during preflight: {rel}")
    for rel, path, old in removals:
        check_path(root, rel)
        if not path.exists() or path.read_bytes() != old:
            raise ValueError(f"File changed during preflight: {rel}")
    backup = None
    if any(old is not None for _, _, old, _ in changes) or removals:
        backup = Path(tempfile.mkdtemp(prefix="git-workflow-backup-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S-") ))
        for rel, _, old, _ in changes:
            if old is not None:
                copy = backup.joinpath(*PurePosixPath(rel).parts)
                copy.parent.mkdir(parents=True,exist_ok=True)
                copy.write_bytes(old)
        for rel, _, old in removals:
            copy = backup.joinpath(*PurePosixPath(rel).parts)
            copy.parent.mkdir(parents=True,exist_ok=True)
            copy.write_bytes(old)
        ui.line("Exact previous-file backup: " + str(backup))
    completed = []
    try:
        with ui.progress(len(changes) + len(removals), "Apply file changes") as advance:
            for rel, path, old, data in changes:
                check_path(root, rel)
                if (path.read_bytes() if path.exists() else None) != old:
                    raise ValueError(f"File changed during installation: {rel}")
                completed.append((path,old,data))
                atomic_write(path, data)
                advance()
            for rel, path, old in removals:
                check_path(root, rel)
                if not path.exists() or path.read_bytes() != old:
                    raise ValueError(f"File changed during installation: {rel}")
                completed.append((path,old,None))
                path.unlink()
                advance()
        if not global_install and old_manifest:
            for name in OLD_NAMES - {"git-workflow"}:
                old_dir = root/'.agents'/'skills'/name
                if old_dir.is_dir() and not old_dir.is_symlink():
                    for subdir in sorted(old_dir.rglob('*'), key=lambda item: len(item.parts), reverse=True):
                        if subdir.is_dir() and not subdir.is_symlink():
                            try: subdir.rmdir()
                            except OSError: pass
                    try: old_dir.rmdir()
                    except OSError: pass
    except BaseException:
        for path, old, written in reversed(completed):
            if written is None and not path.exists() and old is not None:
                atomic_write(path,old)
            elif path.is_file() and not path.is_symlink() and path.read_bytes() == written:
                if old is None:
                    path.unlink()
                else:
                    atomic_write(path, old)
        raise
    ui.step(4, "Installation complete")
    if ui.enabled:
        ui.outcome("Installed Git Workflow", ["Agents: " + ", ".join(selected), "Target: " + str(root),
                   "Ask your agent to use Git Workflow for commitmsg."])
    else:
        print("Installed Git Workflow for " + ", ".join(selected) + ". Ask your agent to use Git Workflow for commitmsg.")
        print("No Git commits, pushes, hooks, or dependency installs were run.")
    if "hermes" in selected and not global_install:
        ui.line("Hermes: run hermes skills trust inside the project before discovery.")
    if "gemini-cli" in selected:
        ui.line("Gemini CLI: /skills reload, then /skills list; workspace must be trusted (/trust).")
    if "kiro" in selected:
        ui.line('Kiro custom agents: include a "skill://.../SKILL.md" resource for the selected project/user directory (default agent auto-discovers).')
    if "oh-my-pi" in selected:
        ui.line("Oh My Pi: native discovery must be enabled; use the same environment/profile in Oh My Pi and this installer.")
    return 0


def find_project_root(start: Path) -> Optional[Path]:
    """Find the nearest ancestor with a Git directory or worktree marker."""
    directory = start.resolve()
    for candidate in (directory, *directory.parents):
        marker = candidate / ".git"
        if marker.is_dir() or marker.is_file():
            return candidate
    return None


def create_parser(ui=None) -> argparse.ArgumentParser:
    parser = WorkflowParser(
        ui=ui,
        prog="git-workflow",
        description="Install or uninstall the bundled Git Workflow skill.",
        epilog=(
            "Project installs use the nearest Git root above the current working "
            "directory. --project selects an existing directory explicitly; "
            "--global selects the current user's skill locations. Changes are "
            "a dry run until --apply is supplied."
        ),
    )
    parser.add_argument(
        "command", nargs="?", choices=tuple(name for name, _ in CLI_COMMANDS),
        help="Operation to perform; installer flags alone default to install",
    )
    scope = parser.add_mutually_exclusive_group()
    scope.add_argument("--project", metavar="PATH", help="Existing project directory")
    scope.add_argument(
        "--global", dest="global_install", action="store_true",
        help="Install selected agent skills for the current user",
    )
    parser.add_argument("--agent", action="append", metavar="ID[,ID...]",
                        help="Agent ID, repeatable/comma-separated, or all; see the agents command")
    parser.add_argument(
        "--uninstall", action="store_true",
        help="Compatibility alias for the uninstall command",
    )
    parser.add_argument("--apply", action="store_true", help="Apply the planned file changes")
    parser.add_argument("--plain", action="store_true", help="Simple output without decoration, color or animation")
    parser.add_argument("--no-color", action="store_true", help="Disable color while keeping terminal layouts")
    parser.add_argument(
        "--replace", action="store_true",
        help="Replace or remove edited package files after saving exact backups",
    )
    parser.add_argument(
        "--version", action="version",
        version=f"Git Workflow {VERSION}",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    arguments = list(sys.argv[1:] if argv is None else argv)
    ui = TerminalUI(plain="--plain" in arguments, no_color="--no-color" in arguments)
    parser = create_parser(ui)
    if not arguments:
        if ui.enabled and sys.stdin.isatty():
            return interactive_menu(parser, parser.parse_args([]), ui)
        parser.print_help()
        return 0
    args = parser.parse_args(arguments)
    if args.command not in (None, "uninstall") and args.uninstall:
        parser.error("Choose install or uninstall; install cannot be combined with --uninstall")
    if args.command in ("menu", "commands", "status", "agents") and (args.apply or args.replace):
        parser.error("--apply and --replace are only available for install and uninstall")
    try:
        agents = select_agents(args.agent)
    except ValueError as exc:
        parser.error(str(exc))
    if args.command == "agents":
        show_agents(ui)
        return 0
    if args.command == "setup" and not args.agent:
        return interactive_menu(parser, args, ui, setup=True)
    if args.command == "menu":
        return interactive_menu(parser, args, ui)
    if args.command == "commands":
        if ui.enabled:
            ui.banner()
        show_commands(ui)
        return 0
    if args.command is None and not args.uninstall and not (args.apply or args.replace or args.project or args.global_install or args.agent):
        parser.print_help()
        return 0

    if args.global_install:
        raw = Path.home()
    elif args.project is not None:
        raw = Path(args.project).expanduser()
    else:
        raw = find_project_root(Path.cwd())
        if raw is None:
            parser.error(
                "No Git repository found above the current working directory. "
                "Run inside a repository, use --project PATH, or choose --global."
            )
    if raw.is_symlink():
        parser.error("Project path must not be a symlink")
    root = raw.resolve()
    if not root.is_dir():
        parser.error("Project directory must already exist")
    try:
        if ui.enabled:
            ui.banner()
            ui.table("Operation", [("Scope", "Current user" if args.global_install else "Project"),
                                   ("Target", str(root)), ("Mode", "Apply" if args.apply else "Read-only / preview")])
        if args.command == "status":
            return installation_status(root, args.global_install, ui, agents or None)
        options = dict(global_install=args.global_install, remove=args.command == "uninstall" or args.uninstall,
                       apply=args.apply, replace=args.replace)
        if agents:
            options["agents"] = agents
        if ui.enabled:
            options["ui"] = ui
        return manage_installation(root, **options)
    except (ValueError, OSError, UnicodeError) as exc:
        error = TerminalUI(plain=not ui.enabled, no_color=not ui.color, stream=sys.stderr)
        error.outcome("Installation stopped: " + str(exc), ["Next: " + error_guidance(str(exc))], ok=False)
        return 2
    except KeyboardInterrupt:
        print("\nOperation cancelled. Completed changes were rolled back; backups remain available.", file=sys.stderr)
        return 130


if __name__ == "__main__":
    raise SystemExit(main())
